// Spec 010 T041: the "More basemaps…" gallery. DATA generated by
// scripts/basemap-catalog.mjs from maplibre-gl-basemap-control (MIT, © 2026
// Qiusheng Wu), plus keyless CARTO GL and VersaTiles styles; this module
// searches and groups it and turns an entry (with its API key, when it needs
// one) into a BasemapCatalogEntry the map can load.
import gallery from './basemapGallery.json'
import type { BasemapCatalogEntry } from './basemapCatalog.js'

/** Google's Map Tiles API session parameters (one session per map type). */
export interface GoogleSessionConfig {
  mapType: string
  language?: string
  region?: string
  layerTypes?: string[]
  overlay?: boolean
}

export interface GalleryBasemap {
  /** The package id, prefixed `g-` (never clashes with a featured id). */
  id: string
  name: string
  provider: string
  providerName: string
  kind: 'raster' | 'vector'
  category: string
  description: string
  /** Sanitized: plain text and `<a href="https://…">` links only. */
  attribution: string
  /** Vector: the style URL (may hold `{api-key}`, Amazon's `{aws-region}`). */
  url?: string
  /** Raster: tile URL templates (may hold `{api-key}`). */
  tiles?: string[]
  /** Google: the Map Tiles API templates used when a key is set (`{session}`, `{api-key}`). */
  sessionTiles?: string[]
  googleSession?: GoogleSessionConfig
  tileSize?: number
  maxzoom?: number
  /** Raster tiles numbered bottom-up. */
  scheme?: 'xyz' | 'tms'
  /** 'optional': works without a key, uses the provider's licensed tiles with one (Google). */
  key: 'none' | 'optional' | 'required'
  /** The URL also needs the user's AWS region (Amazon Location). */
  region?: boolean
  /** The same basemap as a featured row: choosing it chooses that row. */
  featuredId?: string
  /** Something the user should know before choosing it (a datum offset). */
  warning?: string
  tags: string[]
}

export const GALLERY: GalleryBasemap[] = gallery.basemaps as GalleryBasemap[]
export const GALLERY_SOURCE: string = gallery.source

/** Where to get a key, per keyed provider. */
export const KEY_SIGNUP: Record<string, string> = {
  maptiler: 'https://cloud.maptiler.com/account/keys/',
  stadia: 'https://client.stadiamaps.com/signup/',
  protomaps: 'https://protomaps.com/account',
  carto: 'https://carto.com/',
  mapbox: 'https://account.mapbox.com/access-tokens/',
  amazon: 'https://docs.aws.amazon.com/location/latest/developerguide/using-apikeys.html',
  google: 'https://developers.google.com/maps/documentation/tile/get-api-key',
  tianditu: 'https://console.tianditu.gov.cn/',
}

/** The secret's name for a provider's key (HostAdapter.getSecret). */
export function basemapKeyName(provider: string): string {
  return `basemapKey.${provider}`
}

export function galleryCategories(): string[] {
  return [...new Set(GALLERY.map((g) => g.category))].sort()
}

export function galleryProviders(): Array<{ id: string; name: string }> {
  const seen = new Map<string, string>()
  for (const g of GALLERY) seen.set(g.provider, g.providerName)
  return [...seen].map(([id, name]) => ({ id, name })).sort((a, b) => a.name.localeCompare(b.name))
}

export function findGalleryBasemap(id: string): GalleryBasemap | undefined {
  return GALLERY.find((g) => g.id === id)
}

export interface GalleryFilters {
  category?: string | null
  provider?: string | null
  kind?: 'raster' | 'vector' | null
  keylessOnly?: boolean
}

/** Every word of `q` must appear in the name, provider, category, description or tags (any case). */
export function searchGallery(q: string, filters: GalleryFilters = {}, list: readonly GalleryBasemap[] = GALLERY): GalleryBasemap[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean)
  return list.filter((g) => {
    if (filters.category && g.category !== filters.category) return false
    if (filters.provider && g.provider !== filters.provider) return false
    if (filters.kind && g.kind !== filters.kind) return false
    if (filters.keylessOnly && g.key === 'required') return false
    if (!words.length) return true
    const text = [g.name, g.providerName, g.category, g.description, g.kind, ...g.tags].join(' ').toLowerCase()
    return words.every((w) => text.includes(w))
  })
}

/** Providers shown first: the featured ones, then keyless vector styles (GeoLibre leads with OpenFreeMap too). */
const PROVIDER_ORDER = ['openfreemap', 'esri', 'openstreetmap', 'opentopomap', 'carto-gl', 'versatiles', 'maptoolkit']

/**
 * Entries grouped by provider, as GeoLibre's picker groups them: the featured
 * providers first, then keyless vector styles, then the rest A–Z, and providers
 * whose every basemap needs a key last.
 */
export function galleryGroups(list: readonly GalleryBasemap[]): Array<{ provider: string; providerName: string; basemaps: GalleryBasemap[] }> {
  const groups = new Map<string, { provider: string; providerName: string; basemaps: GalleryBasemap[] }>()
  for (const g of list) {
    let group = groups.get(g.provider)
    if (!group) groups.set(g.provider, (group = { provider: g.provider, providerName: g.providerName, basemaps: [] }))
    group.basemaps.push(g)
  }
  const rank = (p: { provider: string; basemaps: GalleryBasemap[] }): number => {
    const i = PROVIDER_ORDER.indexOf(p.provider)
    if (i >= 0) return i
    return p.basemaps.every((g) => g.key === 'required') ? PROVIDER_ORDER.length + 1 : PROVIDER_ORDER.length
  }
  return [...groups.values()].sort((a, b) => rank(a) - rank(b) || a.providerName.localeCompare(b.providerName))
}

const KEY = '{api-key}'
const REGION = '{aws-region}'

/** Drops a `key={api-key}` query parameter (any `…key` name) and the separator it leaves. */
function withoutKeyParam(url: string): string {
  return url.replace(/([?&])[\w-]*key=\{api-key\}(&?)/i, (_m, sep: string, amp: string) => (amp ? sep : '')).replace(/[?&]$/, '')
}

export type GalleryUrls = { url?: string; tiles?: string[]; session?: { tiles: string[]; config: GoogleSessionConfig; key: string } }

/**
 * The entry's URLs with the key (and AWS region) in place. A key-optional entry
 * without a key keeps its keyless URLs; with one, Google's need a session first
 * (resolveGalleryUrls). A key-required one without a key says it needs one.
 */
export function applyKey(g: GalleryBasemap, key: string | null, region: string | null = null): GalleryUrls | { needsKey: true } {
  const k = key?.trim() || null
  const r = region?.trim() || null
  if (g.key === 'required' && !k) return { needsKey: true }
  if (g.region && !r) return { needsKey: true }
  if (g.key === 'optional' && k && g.sessionTiles && g.googleSession) return { session: { tiles: g.sessionTiles, config: g.googleSession, key: k } }
  const fill = (u: string): string => {
    const withRegion = r ? u.split(REGION).join(encodeURIComponent(r)) : u
    return k ? withRegion.split(KEY).join(encodeURIComponent(k)) : withoutKeyParam(withRegion)
  }
  return g.url !== undefined ? { url: fill(g.url) } : { tiles: (g.tiles ?? []).map(fill) }
}

// Adapted from maplibre-gl-basemap-control (MIT, © 2026 Qiusheng Wu), BasemapControl._getGoogleSessionToken.
const googleSessions = new Map<string, { token: string; expiry: number }>()

/** A Map Tiles API session token for this key and map type (cached until a minute before it expires). */
export async function googleSessionToken(key: string, config: GoogleSessionConfig, fetchImpl: typeof fetch = fetch): Promise<string> {
  const cacheKey = `${key}:${JSON.stringify(config)}`
  const cached = googleSessions.get(cacheKey)
  if (cached && cached.expiry - 60_000 > Date.now()) return cached.token
  const response = await fetchImpl(`https://tile.googleapis.com/v1/createSession?key=${encodeURIComponent(key)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ mapType: config.mapType, language: config.language ?? 'en-US', region: config.region ?? 'US', layerTypes: config.layerTypes, overlay: config.overlay }),
  })
  if (!response.ok) throw new Error(`Google could not create a tile session (HTTP ${response.status}). Check that the Map Tiles API is enabled for the key.`)
  const data = (await response.json()) as { session?: string; expiry?: string }
  if (!data.session) throw new Error('Google did not return a tile session. Check that the Map Tiles API is enabled for the key.')
  const seconds = Number(data.expiry)
  googleSessions.set(cacheKey, { token: data.session, expiry: Number.isFinite(seconds) ? seconds * 1000 : Date.now() + 3_600_000 })
  return data.session
}

/** applyKey, with Google's session resolved into tile URLs. */
export async function resolveGalleryUrls(
  g: GalleryBasemap,
  key: string | null,
  region: string | null = null,
  fetchImpl: typeof fetch = fetch
): Promise<{ url?: string; tiles?: string[] } | { needsKey: true }> {
  const urls = applyKey(g, key, region)
  if ('needsKey' in urls || !urls.session) return urls
  const token = await googleSessionToken(urls.session.key, urls.session.config, fetchImpl)
  const k = encodeURIComponent(urls.session.key)
  return { tiles: urls.session.tiles.map((t) => t.split('{session}').join(encodeURIComponent(token)).split(KEY).join(k)) }
}

/** A gallery entry, its URLs resolved, as the map's catalog entry; `keyed` when a key was applied. */
export function toCatalogEntry(g: GalleryBasemap, resolved: { url?: string; tiles?: string[] }, keyed = false): BasemapCatalogEntry {
  return {
    id: g.id,
    name: g.name,
    type: g.kind,
    url: resolved.url ?? resolved.tiles?.[0] ?? '',
    ...(resolved.tiles ? { tiles: resolved.tiles } : {}),
    attribution: g.attribution,
    requiresKey: g.key === 'required',
    region: 'global',
    provider: g.provider,
    providerName: g.providerName,
    ...(keyed ? { keyed: true } : {}),
    ...(g.maxzoom !== undefined ? { maxzoom: g.maxzoom } : {}),
    ...(g.tileSize !== undefined ? { tileSize: g.tileSize } : {}),
    ...(g.scheme !== undefined ? { scheme: g.scheme } : {}),
  }
}
